using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var searchApiKey = Environment.GetEnvironmentVariable("SEARCH_API_KEY") ?? "";
var searchEngineId = Environment.GetEnvironmentVariable("SEARCH_ENGINE_ID") ?? "";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptUser("Enter a research topic: ");

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Build the chat client with automatic tool invocation ---
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient("gpt-4o")
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Tools ---
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query string")] string query) =>
            WebSearch.SearchAsync(query, searchApiKey, searchEngineId),
        "web_search",
        "Searches the web for a query and returns a list of result titles, snippets, and URLs. Use this to gather information on a topic."),

    AIFunctionFactory.Create(
        ([Description("A concise heading for the note")] string heading,
         [Description("The note content (facts, quotes, data)")] string content) =>
        {
            notebook.Add(heading, content);
            return $"Note saved under \"{heading}\".";
        },
        "take_note",
        "Saves a research note. Use this to record important findings so they can be referenced in the final summary."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "read_notes",
        "Returns all notes taken so far. Use before writing the final summary to review collected research."),
};

// --- Agent loop ---
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic and
        produce a well-structured summary.

        Workflow:
        1. Search the web for the topic (use 2-4 varied queries to get broad coverage).
        2. After each search, take notes on the most important findings.
        3. Once you have enough material, read your notes and write a final summary.
        4. The final summary should be detailed, cite sources where possible, and be
           organized with clear headings.
        """),
    new(ChatRole.User, $"Research this topic and provide a comprehensive summary: {topic}"),
};

var options = new ChatOptions { Tools = [.. tools] };

var response = await client.GetResponseAsync(messages, options);
Console.WriteLine("\n📝 Final Report:\n");
Console.WriteLine(response.Text);

// --- Helper ---
static string PromptUser(string prompt)
{
    Console.Write(prompt);
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input) ? "Artificial Intelligence in 2026" : input;
}

// ============================================================
// Supporting types
// ============================================================

/// <summary>Simple in-memory notebook for the agent to store findings.</summary>
class Notebook
{
    private readonly List<(string Heading, string Content)> _notes = [];

    public void Add(string heading, string content) => _notes.Add((heading, content));

    public string GetAll() =>
        _notes.Count == 0
            ? "(no notes yet)"
            : string.Join("\n\n", _notes.Select((n, i) =>
                $"### Note {i + 1}: {n.Heading}\n{n.Content}"));
}

/// <summary>Web search via Google Custom Search JSON API with a fallback for missing keys.</summary>
static class WebSearch
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query, string apiKey, string engineId)
    {
        Console.WriteLine($"  🌐 Searching: {query}");

        if (string.IsNullOrEmpty(apiKey) || string.IsNullOrEmpty(engineId))
            return SimulatedSearch(query);

        var url = $"https://www.googleapis.com/customsearch/v1?q={Uri.EscapeDataString(query)}" +
                  $"&key={apiKey}&cx={engineId}&num=5";

        try
        {
            var doc = await Http.GetFromJsonAsync<JsonDocument>(url);
            var items = doc?.RootElement.GetProperty("items").EnumerateArray() ?? default;
            var results = new List<string>();

            foreach (var item in items)
            {
                var title = item.GetProperty("title").GetString();
                var snippet = item.GetProperty("snippet").GetString();
                var link = item.GetProperty("link").GetString();
                results.Add($"- **{title}**\n  {snippet}\n  Source: {link}");
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search failed ({ex.Message}). Falling back to simulated results.\n\n{SimulatedSearch(query)}";
        }
    }

    private static string SimulatedSearch(string query)
    {
        return $"""
            (Simulated results — set SEARCH_API_KEY and SEARCH_ENGINE_ID for live search)

            - **Overview of {query} — Wikipedia**
              A comprehensive overview covering history, key concepts, and recent developments.
              Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}

            - **Latest advances in {query} — TechReview**
              Recent breakthroughs and trends shaping the field as of 2026.
              Source: https://techreview.example.com/{Uri.EscapeDataString(query)}

            - **{query}: Expert analysis — ResearchHub**
              In-depth expert analysis including data, case studies, and future outlook.
              Source: https://researchhub.example.com/{Uri.EscapeDataString(query)}
            """;
    }
}

